sInf { v : ℝ | ∃ w : Fin (k + 1) → ℝ, UnbiasedWeights beta k p w ∧
  v = sigma0sq / (n : ℝ) * (∑ j, |w j|) ^ 2 }
= sigma0sq / (n : ℝ) * amplification beta k p

sInf { v : ℝ | ∃ p' : Fin (k + 1) → ℝ, BudgetedSchedule k q p' ∧
  v = sigma0sq / (n : ℝ) * amplification beta k p' }
= sigma0sq / (n : ℝ) * minimaxAmplification beta k q

UnbiasedWeights beta beta (equalSchedule beta 1)
(fun j => if j = (0 : Fin (beta + 1)) then -1
  else if j = Fin.last beta then 1 else 0)

sInf { s : ℝ | ∃ w : Fin (k + 1) → ℝ, UnbiasedWeights beta k p w ∧ s = ∑ j, |w j| }
= sSup { t : ℝ | ∃ r : Polynomial ℝ, r.natDegree ≤ beta ∧
    (∀ j, |r.eval (p j)| ≤ 1) ∧ t = |r.eval 1 - r.eval 0| }
